<script setup lang="ts">
import{onBeforeUnmount,onMounted,reactive,ref}from'vue';import{api,session}from'../api';import StatusPill from'../components/StatusPill.vue'
const rows=ref<any[]>([]),organizations=ref<any[]>([]),loading=ref(false),error=ref(''),updated=ref(''),timer=ref<number>();const filters=reactive({organization_id:'',room_id:'',status:'',version:''})
async function load(){loading.value=true;error.value='';try{const p=new URLSearchParams();Object.entries(filters).forEach(([k,v])=>{if(v)p.set(k,v)});const path=session.role==='platform_super'?`/api/v2/platform/devices?${p}`:`/api/v2/organization/devices?${p}`;rows.value=(await api(path)).items;updated.value=new Date().toLocaleTimeString()}catch(e:any){error.value=e.message}finally{loading.value=false}}
async function boot(){if(session.role==='platform_super'){organizations.value=(await api('/tk-api/customers')).customers||[];if(!filters.organization_id&&organizations.value.length)filters.organization_id=String(organizations.value[0].id)}if(filters.organization_id||session.role!=='platform_super')await load();timer.value=window.setInterval(()=>{if(!document.hidden)load()},15000)}
onMounted(boot);onBeforeUnmount(()=>{if(timer.value)clearInterval(timer.value)})
</script>
<template><div class="page-stack"><section class="panel"><header class="panel-head"><div><span class="eyebrow">DEVICE OPERATIONS</span><h2>实时设备</h2><p>快速判断哪些电脑正常，哪些需要立即处理。</p></div><small>更新于 {{updated||'-'}}</small></header><div class="filter-grid"><select v-if="session.role==='platform_super'" v-model="filters.organization_id"><option value="" disabled>选择企业</option><option v-for="org in organizations" :value="String(org.id)">{{org.name}}</option></select><input v-model="filters.room_id" placeholder="直播间"><select v-model="filters.status"><option value="">全部状态</option><option value="online">在线</option><option value="unstable">不稳定</option><option value="offline">离线</option></select><input v-model="filters.version" placeholder="客户端版本"><button @click="load">筛选</button></div><div v-if="error" class="state-inline error"><b>暂时无法加载设备</b><span>{{error}}</span><button @click="load">立即重试</button></div><div v-if="loading&&!rows.length" class="skeleton-stack"><i v-for="n in 5" class="skeleton"></i></div><div v-else class="realtime-grid"><article v-for="x in rows" :class="x.online_state||'offline'"><header><div><b>{{x.display_name}}</b><small>{{x.device_id}}</small></div><StatusPill :value="x.online_state||(x.online?'online':'offline')"/></header><dl><div><dt>当前绑定</dt><dd>{{x.binding?`直播间 #${x.binding.room_id}`:'未绑定'}}</dd></div><div><dt>客户端版本</dt><dd>{{x.agent_version||'-'}}</dd></div><div><dt>直播软件</dt><dd><StatusPill :value="x.studio_state||'not_running'"/></dd></div><div><dt>采集状态</dt><dd><StatusPill :value="x.collector_state||'unknown'"/></dd></div></dl><div class="metric-line"><span>CPU {{x.metrics?.cpu_percent??'-'}}%</span><span>内存 {{x.metrics?.memory_percent??'-'}}%</span><span>延迟 {{x.metrics?.network_latency_ms??'-'}}ms</span><span>上传 {{x.metrics?.upload_mbps??'-'}}Mbps</span></div><footer>最后心跳 {{x.last_heartbeat_at?.replace('T',' ').slice(0,19)||'尚未上报'}}</footer></article><div v-if="!rows.length" class="empty-state"><b>还没有接入设备</b><p>安装客户端并绑定直播间后，设备会显示在这里。</p></div></div></section></div></template>
